/// The version constraints `create` and `init` write on this repository's
/// packages, in one place.
///
/// **A caret on each package's own version at this release**, so a project
/// generated by a template that uses a 1.3 API asks for 1.3 and does not
/// resolve 1.0 and fail to compile. A package's version moves with its
/// release; `template_versions_test` reads every pubspec in the workspace
/// and holds each entry to `^<its version>`, so a release that bumps one
/// and not the other fails there.
library;

/// Each package a template depends on, with the constraint it writes.
const Map<String, String> templateConstraints = <String, String>{
  'flame_flutter3d': '^1.0.0-rc.1+1',
  'flutter3d': '^1.0.0-rc.1+2',
  'flutter3d_app': '^1.0.0-rc.1+1',
  'flutter3d_build': '^1.0.0-rc.1+1',
  'flutter3d_conformance': '^1.0.0-rc.1+2',
  'flutter3d_core': '^1.0.0-rc.1+2',
  'flutter3d_fields': '^1.0.0-rc.1',
  'flutter3d_foundation': '^1.0.0-rc.1+1',
  'flutter3d_hardware': '^1.0.0-rc.1+2',
  'flutter3d_plugin_api': '^1.0.0-rc.1+1',
  'flutter3d_shaders': '^1.0.0-rc.1+1',
  'flutter3d_sim': '^1.0.0-rc.1+1',
};

/// `  <package>: <constraint>`, the pubspec line a template writes for
/// [package].
String dependencyLine(String package) =>
    '  $package: ${templateConstraints[package]!}';
